package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;
import net.officefloor.hq.app.statement.Rounding;
import net.officefloor.hq.app.setting.SettingHistory;

/** The rules of a claim's status change and its audit line, shared by a single change ({@link SaveClaimStatus},
 *  {@link AuditClaimStatus}) and a bulk settle ({@link BulkSettleClaims}). */
final class ClaimStatusChange {
    private ClaimStatusChange() {
    }

    /** How many days after its settlement (by the sheet's today, as its status log records it) a steward may still
     *  void a SETTLED claim. */
    private static final int VOID_SETTLED_DAYS = 7;

    /** Move the claim to its new status as {@link SaveClaimStatus} describes, adding it to its status log: the claim
     *  as stored now; throws (having written nothing) when the change is not allowed. */
    static ClaimResponse save(ClaimStatusInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log)
            throws ClaimStatusNotAllowedException {
        ClaimStatus to = check(input, loaded, repository, people, rates, roles, settings, sheets, log);
        boolean opening = input.action().equals("open");
        String openedBy = opening ? input.user() : loaded.openedBy();
        // a claim gone to REVIEW is numbered only once a steward reviews it OPEN
        String number = (opening && to == ClaimStatus.OPEN) || input.action().equals("review")
                ? repository.nextNumber(loaded.sheetId(), loaded.dueBy()) : loaded.number();
        BigDecimal settledDue = input.action().equals("resettle")
                ? dueNow(asOpenUnstated(loaded), repository, people, rates, settings, sheets)
                : to == ClaimStatus.SETTLED && input.action().equals("settle") && input.on() != null
                        ? dueAsOf(then(loaded, input.on(), repository), input.on(), repository, people, rates, settings, sheets)
                : to == ClaimStatus.SETTLED ? dueNow(loaded, repository, people, rates, settings, sheets)
                : to == ClaimStatus.VOID && loaded.status() == ClaimStatus.SETTLED ? loaded.settledDue() : null;
        if (!repository.changeStatus(loaded, to, number, settledDue, openedBy)) {
            // the transaction rolls back, so a number taken above is not used up
            throw new ClaimStatusNotAllowedException(loaded.status(), to);
        }
        log.record(loaded, input.user());
        return ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                loaded.date(), loaded.note(), to, number, settledDue, openedBy, loaded.stated(),
                loaded.statedDue(), loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(), loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags(), loaded.waived(), loaded.photos(), loaded.held()));
    }

    /** The status the claim would move to by the change as {@link SaveClaimStatus} describes (PENDING for a clerk's
     *  settle above the clerk limit), writing nothing; throws when the change is not allowed. */
    static ClaimStatus check(ClaimStatusInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log)
            throws ClaimStatusNotAllowedException {
        ClaimStatus to = input.to();
        if (Permissions.ACTIONS.contains(input.action()) && !settings.permissions(loaded.sheetId())
                .allows(input.action(), roles.of(loaded.sheetId(), input.user()))) {
            throw new ClaimStatusNotAllowedException("Your role may not " + input.action() + " a claim on this sheet.");
        }
        boolean review = input.action().equals("approve") || input.action().equals("reject");
        if (review) {
            if (loaded.status() != ClaimStatus.PENDING) {
                throw new ClaimStatusNotAllowedException("Only a PENDING claim can be " + input.action()
                        + "d; this one is " + loaded.status() + ".");
            }
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))
                    && !input.user().equals(people.approver(loaded.sheetId(), loaded.personId()))) {
                throw new ClaimStatusNotAllowedException("Only a steward or the person's approver can "
                        + input.action() + " a PENDING claim.");
            }
            if (input.action().equals("approve") && input.user().equals(loaded.openedBy())) {
                throw new ClaimStatusNotAllowedException("The user who opened a claim cannot approve it.");
            }
            if (input.action().equals("approve") && input.user().equals(repository.editedBy(loaded))) {
                throw new ClaimStatusNotAllowedException("The user who last edited a claim cannot approve it.");
            }
        } else if (input.action().equals("review")) {
            if (loaded.status() != ClaimStatus.REVIEW) {
                throw new ClaimStatusNotAllowedException("Only a REVIEW claim can be reviewed; this one is "
                        + loaded.status() + ".");
            }
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can review a claim.");
            }
        } else if (input.action().equals("resettle")) {
            if (loaded.status() != ClaimStatus.SETTLED) {
                throw new ClaimStatusNotAllowedException("Only a SETTLED claim can be re-settled; this one is "
                        + loaded.status() + ".");
            }
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can re-settle a claim.");
            }
        } else if (input.action().equals("void") && loaded.status() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
                throw new ClaimStatusNotAllowedException("Only a steward can void a SETTLED claim.");
            }
            LocalDate settledOn = log.lastOn(loaded.sheetId(), loaded.id(), ClaimStatus.SETTLED);
            LocalDate today = sheets.today(loaded.sheetId());
            if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new ClaimStatusNotAllowedException("A SETTLED claim can only be voided within "
                        + VOID_SETTLED_DAYS + " days of its settlement.");
            }
        } else if (input.action().equals("restore")) {
            if (loaded.status() != ClaimStatus.DELETED) {
                throw new ClaimStatusNotAllowedException("Only a DELETED claim can be restored; this one is "
                        + loaded.status() + ".");
            }
            LocalDate deletedOn = log.lastOn(loaded.sheetId(), loaded.id(), ClaimStatus.DELETED);
            LocalDate today = sheets.today(loaded.sheetId());
            if (deletedOn == null || !deletedOn.equals(today)) {
                throw new ClaimStatusNotAllowedException("A DELETED claim can only be restored on the day it was deleted.");
            }
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed",
                Long.class, sheetId, fromId)) {
            jdbc.update("UPDATE claim SET person_id = ?, "
                    + "listed = NEXT VALUE FOR claim_listed_seq WHERE sheet_id = ? AND id = ?", toId, sheetId, id);
            kept(sheetId, id);
        }
    }

    /** Move every claim of the person to another sheet, keeping its place in their list, its status, dates, note,
     *  settled due, tags, comments, lines and log: each claim that had a number takes the next number of the other sheet,
     *  in the order the claims were added; each keeps the figure a statement bound it to, loses its reference, editor lock and
     *  settle batch, and its history here is dropped (it is kept anew on the other sheet). */
    public void transfer(String sheetId, long personId, String toSheet) {
        List<Claim> theirs = listForPerson(sheetId, personId).stream()
                .sorted(java.util.Comparator.comparingLong(Claim::id)).toList();
        for (Claim c : theirs) {
            String number = c.number() != null ? nextNumber(toSheet, c.dueBy()) : null;
            jdbc.update("UPDATE claim SET sheet_id = ?, claim_number = ?, due_by = ?, "
                    + "ref = NULL, locked_by = NULL WHERE sheet_id = ? AND id = ?", toSheet, number, c.dueBy(), sheetId,
                    c.id());
            for (String table : List.of("claim_log", "claim_comment", "claim_line", "claim_void_reason")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", toSheet,
                        sheetId, c.id());
            }
            for (String table : List.of("claim_batch", "claim_history")) {
                jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND claim_id = ?", sheetId, c.id());
            }
            kept(toSheet, c.id());
            used(toSheet, c.tags());
        }
    }

    /** Defer the claim until the date: false when it is no longer OPEN (another user changed it first), and nothing
     *  is written. */
    public boolean defer(Claim claim, LocalDate until) {
        return kept(claim, jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet_id = ? AND id = ? AND status = ?",
                until, claim.sheetId(), claim.id(), ClaimStatus.OPEN.name()) == 1);
    }

    /** Mark the claim reminded on the day: false when it is no longer OPEN or PENDING, or was already reminded that
     *  day (another user got there first), and nothing is written. */
    public boolean remind(Claim claim, LocalDate on) {
        return kept(claim, jdbc.update(
                "UPDATE claim SET reminded_on = ? WHERE sheet_id = ? AND id = ? AND status IN (?, ?) AND (reminded_on IS NULL OR reminded_on <> ?)",
                on, claim.sheetId(), claim.id(), ClaimStatus.OPEN.name(), ClaimStatus.PENDING.name(), on) == 1);
    }

    /** Waive the claim's late charge: false when it is no longer OPEN or PENDING, or was already waived (another
     *  user got there first), and nothing is written. */
    public boolean waive(Claim claim) {
        return kept(claim, jdbc.update(
                "UPDATE claim SET waived = TRUE WHERE sheet_id = ? AND id = ? AND status IN (?, ?) AND waived = FALSE",
                claim.sheetId(), claim.id(), ClaimStatus.OPEN.name(), ClaimStatus.PENDING.name()) == 1);
    }

    /** Hold or release the claim: false when it is no longer OPEN or PENDING, or is already so (another user got there
     *  first), and nothing is written. */
    public boolean hold(Claim claim, boolean held) {
        return kept(claim, jdbc.update(
                "UPDATE claim SET held = ? WHERE sheet_id = ? AND id = ? AND status IN (?, ?) AND held = ?",
                held, claim.sheetId(), claim.id(), ClaimStatus.OPEN.name(), ClaimStatus.PENDING.name(), !held) == 1);
     *  date and status it was loaded with (another user changed it first), and nothing is written. */
    public boolean redate(Claim claim, LocalDate date, String number) {
        return kept(claim, jdbc.update(
                "UPDATE claim SET claim_date = ?, claim_number = ? WHERE sheet_id = ? AND id = ? AND claim_date = ? AND status = ?",
                date, number, claim.sheetId(), claim.id(), claim.date(), claim.status().name()) == 1);
    }

    /** Whether the sheet numbers claims within their period now: its period numbering from is a date and its today
     *  is on or after it. */
    public boolean numberingByPeriod(String sheetId) {
        return Boolean.TRUE.equals(jdbc.query(
                "SELECT period_numbering_from IS NOT NULL AND today >= period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId));
    }

    /** Take the next number for a claim due by the date, as it is opened. While the sheet's period numbering from
     *  is a date and the sheet's today is on or after it, that is the next in the claim's period (the one holding its due-by: <period name>-<n>),
     *  or for a claim in no period the next in its own sequence (X-<n>); otherwise it is the next number of the
     *  sheet's tree (the sheet's root, reached through its parents, and every descendant of the root) within the
     *  fiscal year of the due-by (by this sheet's fiscal year start month): FY<yyyy>-<n>, one after the last number
     *  given in that fiscal year on any sheet of the tree, recorded as this sheet's last number for that year.
     *  Taking a number locks the sheet's row (and, for a tree number, every row of the tree, in id order) until the
     *  transaction ends, so concurrent openings are numbered one after the other; a rolled-back one gives its number
     *  back, so there are no gaps. */
    public String nextNumber(String sheetId, LocalDate date) {
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
        Boolean byPeriod = jdbc.query(
                "SELECT period_numbering_from IS NOT NULL AND today >= period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getBoolean(1) : false, sheetId);
        if (!Boolean.TRUE.equals(byPeriod)) {
            Set<String> tree = tree(sheetId);
            String in = String.join(",", Collections.nCopies(tree.size(), "?"));
            Object[] ids = tree.toArray();
            jdbc.query("SELECT id FROM sheet WHERE id IN (" + in + ") ORDER BY id FOR UPDATE", rs -> null, ids);
            int fy = fiscalYear(sheetId, date);
            Object[] args = new Object[ids.length + 1];
            System.arraycopy(ids, 0, args, 0, ids.length);
            args[ids.length] = fy;
            Integer last = jdbc.queryForObject("SELECT MAX(last_number) FROM fiscal_year_number WHERE sheet_id IN ("
                    + in + ") AND fiscal_year = ?", Integer.class, args);
            int next = (last == null ? 0 : last) + 1;
            if (jdbc.update("UPDATE fiscal_year_number SET last_number = ? WHERE sheet_id = ? AND fiscal_year = ?",
                    next, sheetId, fy) == 0) {
                jdbc.update("INSERT INTO fiscal_year_number (sheet_id, fiscal_year, last_number) VALUES (?, ?, ?)",
                        sheetId, fy, next);
            }
            return "FY" + fy + "-" + next;
        }
        String[] period = jdbc.query(
                "SELECT name, name_key FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ? ORDER BY from_date",
                rs -> rs.next() ? new String[] { rs.getString(1), rs.getString(2) } : null, sheetId, date, date);
        String prefix = period != null ? period[0] : "X";
        String key = period != null ? "p:" + period[1] : "x";
        if (jdbc.update("UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_key = ?",
                sheetId, key) == 0) {
            jdbc.update("INSERT INTO period_number (sheet_id, seq_key, last_number) VALUES (?, ?, 1)", sheetId, key);
        }
        int n = jdbc.queryForObject("SELECT last_number FROM period_number WHERE sheet_id = ? AND seq_key = ?",
                Integer.class, sheetId, key);
        return prefix + "-" + n;
    }

    /** The fiscal year holding the date by the sheet's fiscal year start month, named by the calendar year its
     *  first day falls in. */
    private int fiscalYear(String sheetId, LocalDate date) {
        Integer month = jdbc.query("SELECT fiscal_start_month FROM sheet WHERE id = ?",
                rs -> rs.next() ? (Integer) rs.getObject(1, Integer.class) : null, sheetId);
        int start = month != null ? month : 1;
        return date.getMonthValue() >= start ? date.getYear() : date.getYear() - 1;
    }

    /** The sheets of the sheet's tree, in id order: its root (its parent's parent, and so on, up to a sheet with
     *  none) and every descendant of the root. */
    private Set<String> tree(String sheetId) {
        Set<String> up = new LinkedHashSet<>();
        String root = sheetId;
        for (String at = sheetId; at != null && up.add(at); at = parentOf(at)) {
            root = at;
        }
        Set<String> tree = new TreeSet<>();
        Deque<String> todo = new ArrayDeque<>(List.of(root));
        while (!todo.isEmpty()) {
            String at = todo.pop();
            if (tree.add(at)) {
                todo.addAll(jdbc.queryForList("SELECT id FROM sheet WHERE parent = ?", String.class, at));
            }

